// Package payload carries the server source that `covee setup` installs. It is
// generated by scripts/build_cli.py and embedded so the CLI and the server it
// installs always come from the same reviewed tree.
package payload

import (
	"archive/tar"
	"bytes"
	"compress/gzip"
	"crypto/sha256"
	"embed"
	"encoding/hex"
	"errors"
	"fmt"
	"io"
	"io/fs"
	"path"
	"strings"
)

//go:embed assets
var assets embed.FS

// ErrMissing reports a CLI built without scripts/build_cli.py.
var ErrMissing = errors.New("this covee binary was built without the server payload; build it with scripts/build_cli.py")

// Archive returns the gzipped tar of the server source and its SHA-256.
func Archive() ([]byte, string, error) {
	data, err := assets.ReadFile("assets/payload.tar.gz")
	if errors.Is(err, fs.ErrNotExist) {
		return nil, "", ErrMissing
	}
	if err != nil {
		return nil, "", err
	}
	sum := sha256.Sum256(data)
	return data, hex.EncodeToString(sum[:]), nil
}

// File returns one file of a payload archive, such as "scripts/dns_updater.py".
func File(archive []byte, name string) ([]byte, error) {
	gz, err := gzip.NewReader(bytes.NewReader(archive))
	if err != nil {
		return nil, fmt.Errorf("reading the Covee files: %w", err)
	}
	defer gz.Close()
	tr := tar.NewReader(gz)
	for {
		h, err := tr.Next()
		if errors.Is(err, io.EOF) {
			return nil, fmt.Errorf("the Covee files do not contain %s; this covee binary is older than that feature", name)
		}
		if err != nil {
			return nil, fmt.Errorf("reading the Covee files: %w", err)
		}
		if path.Clean(strings.TrimPrefix(h.Name, "./")) == name && h.Typeflag == tar.TypeReg {
			return io.ReadAll(io.LimitReader(tr, 4<<20))
		}
	}
}
